const assert = require('node:assert/strict');
const fs = require('node:fs');
const crypto = require('node:crypto');
const pkg = '/workspace/rutcampustrack/frontends/node_modules/@vue/runtime-dom';
const source = fs.readFileSync(pkg + '/dist/runtime-dom.cjs.js');
const { patchProp } = require(pkg);
assert.equal(typeof patchProp, 'function');
const priorNow = Date.now;
let ticks = 1000000000000;
const outcomes = [];
function element() {
  const listeners = [];
  return { listeners, addEventListener(type, listener, options) {
    listeners.push({ type, listener, capture: options?.capture === true });
  }, removeEventListener() {} };
}
async function witness(advance) {
  const parent = element(), child = element();
  const calls = { capture: 0, target: 0 };
  patchProp(parent, 'onClickCapture', null, () => { calls.capture += 1; });
  patchProp(child, 'onClick', null, () => { calls.target += 1; });
  assert.equal(parent.listeners.length, 1);
  assert.equal(child.listeners.length, 1);
  assert.equal(parent.listeners[0].capture, true);
  assert.equal(child.listeners[0].capture, false);
  await Promise.resolve();
  if (advance) ticks += 1;
  const event = {};
  parent.listeners[0].listener(event);
  child.listeners[0].listener(event);
  return calls;
}
(async () => {
  try {
    Date.now = () => ticks;
    const frozen = await witness(false);
    ticks += 1000;
    const progressing = await witness(true);
    assert.deepEqual(frozen, { capture: 1, target: 0 });
    assert.deepEqual(progressing, { capture: 1, target: 1 });
    outcomes.push(frozen, progressing);
  } finally {
    Date.now = priorNow;
  }
  assert.equal(Date.now, priorNow);
  const receiptPath = '/workspace/scratch/rct-validation/q09_remaining_client_writer/homework-inbox-current874.safe.json';
  const receipt = JSON.parse(fs.readFileSync(receiptPath, 'utf8'));
  const scope = receipt.current62df_Homework_fail_diagnosis;
  assert.equal(scope.causal_control, undefined);
  scope.causal_control = {
    state: 'PASS_ACTUAL_INSTALLED_VUE_PUBLIC_PATCHPROP_COUNTEREXAMPLE',
    version: require(pkg + '/package.json').version,
    cjs_sha256: crypto.createHash('sha256').update(source).digest('hex'),
    method: 'Actual exported patchProp registers exact runtime invokers on tiny addEventListener ports; shared event dispatches ancestor capture then child. No invoker implementation copied.',
    frozen: outcomes[0], progressing: outcomes[1], original_Date_now_restored: Date.now === priorNow,
    browser_run: false, product_run: false,
    limitations: 'Framework event-invoker control only; no DOM layout/browser/live user-flow acceptance.'
  };
