const title='FULL admin reconciles one exact stranded close before archive completion';
function getCase(text){const source=ts.createSourceFile('fixture.ts',text,ts.ScriptTarget.Latest,true);let result;function walk(n){if(ts.isCallExpression(n)&&n.arguments[0]&&ts.isStringLiteral(n.arguments[0])&&n.arguments[0].text===title){assert(!result);result=n.arguments[1].body;}ts.forEachChild(n,walk);}walk(source);assert(result);return{source,body:result};}
