let controls=0;
async function run(name,options={}){
 let now=0,reads=0,delays=0,upCalls=0;const trace=[];const cap=options.budget??45000;
 const id='a'.repeat(64);const service='attendance-service';const pin={id,image:'sha256:synthetic',labels:{'com.docker.compose.project':'rct-e2e','com.docker.compose.service':service},mounts:[{Type:'bind',Source:'synthetic-clock',Destination:'/clock',RW:false}]};
 let lastHealth='starting';let releasedAt;
 const stopped=new Set(options.notStopped?[]:[service]);const originalDelete=stopped.delete.bind(stopped);
 stopped.delete=(s)=>{assert.equal(lastHealth,'healthy');assert(now<=cap);releasedAt=now;trace.push('release');return originalDelete(s);};
 const diagnostic={firstRestartFailure:null};
 const scope={root:'/synthetic',nativeEnv:{},compose:['compose','fixed'],pins:{[service]:pin},stopped,diagnostic,cleaning:options.cleaning??false,performance:{now:()=>now},budget:maximum=>Math.min(maximum,cap-now),requireValue:(value,message)=>{if(!value)throw new Error(message);},equal:(left,right,message)=>{if(JSON.stringify(left)!==JSON.stringify(right))throw new Error(message);},setTimeout:(callback,delay)=>{assert(delay>0);assert(delay<=Math.max(0,cap-now));delays++;now+=options.earlyTimer?Math.max(.5,delay-.5):delay;queueMicrotask(callback);return 1;},execFileSync:(command,args,params)=>{
  assert.equal(command,'docker');assert(params.timeout>0);if(!options.old)assert(params.timeout<=cap-now);
