  now+=duration;
  if(!inspect){upCalls++;assert.deepEqual(Array.from(args),['compose','fixed','up','-d','--no-build','--no-recreate','--no-deps','--pull','never','--wait','--wait-timeout','40',service]);return '';}
  reads++;
  const state=reads===1?{running:false,health:'healthy'}:{running:true,health:options.health??(reads<3?'starting':'healthy')};
  if(options.permanent&&reads>1)state.health='starting';
  if(options.runningFalse&&reads>1)state.running=false;
  const value={...pin,...state,networks:{}};
  if(options.idDrift&&reads===2)value.id='b'.repeat(64);
  if(options.mountDrift&&reads===2)value.mounts=[{...pin.mounts[0],Source:'other-owned-path'}];
  lastHealth=value.health;return JSON.stringify(value);
 }};
