 let failure;
 try{await scope.restartUnderTest(service);}catch(error){failure=error;}
 if(options.accept){assert(!failure,name+': '+failure?.message);assert(!stopped.has(service));assert.equal(diagnostic.firstRestartFailure,null);assert(releasedAt!==undefined);}
 else if(options.notStopped){assert(!failure);assert.equal(trace.length,0);assert.equal(delays,0);}
 else{assert(failure,name);assert(stopped.has(service));assert.equal(releasedAt,undefined);}
 if(options.message)assert.equal(failure?.message,options.message,name);
 if(options.cause)assert.equal(diagnostic.firstRestartFailure?.cause,options.cause,name);
 if(options.phase)assert.equal(diagnostic.firstRestartFailure?.phase,options.phase,name);
 if(options.maxReads!==undefined)assert.equal(reads,options.maxReads,name);
 if(options.noDelay)assert.equal(delays,0,name);
 if(!options.old)assert(now<=cap,name+' exceeded original absolute budget');
 controls++;
 return{now,reads,delays,trace,upCalls};
}
