function projectClosedHints(raw) {
  'use strict';
  const contract = __FROZEN_CONTRACT__;
  const stages = contract.stages;
  const states = new Set(contract.states);
  const categories = new Set(contract.categories);
  const origins = new Set(contract.origins);
  const classNames = new Set([...Object.keys(contract.classes), 'UNKNOWN']);
  if (typeof raw !== 'string') throw new Error('CLOSED_LOG_INPUT');
  const receivedBytes = encodeURIComponent(raw).replace(/%[A-F\d]{2}/gi, 'x').length;
  if (receivedBytes > 33554432) throw new Error('POST_RESPONSE_LOG_CAP');
  const by = Object.fromEntries(stages.map(stage => [stage, []]));
  const rejected = Object.fromEntries(stages.map(stage => [stage, 0]));
  let invalidClosedCandidateCount = 0;
  let unknownStageCount = 0;
  const exactKeys = (value, expected) => value !== null && typeof value === 'object'
    && !Array.isArray(value) && JSON.stringify(Object.keys(value).sort()) === JSON.stringify(expected);
  const topKeys = ['exceptionCategory', 'reportedExceptionChain', 'reportedExceptionClassChain', 'reportedOrigin', 'reportedOwnFrame', 'sourceStage', 'state'];
  for (const line of raw.split('\n')) {
    const textLine = line.replace(/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?Z\s+/, '').trim();
    if (!textLine.startsWith('{')) continue;
    const potentialStages = stages.filter(stage => textLine.includes('"' + stage + '"'));
    let value;
    try { value = JSON.parse(textLine); } catch {
      if (potentialStages.length) {
        invalidClosedCandidateCount++;
        for (const stage of potentialStages) rejected[stage]++;
      }
      continue;
    }
    if (value === null || typeof value !== 'object' || Array.isArray(value)) continue;
    const target = stages.includes(value.sourceStage);
    if (!target && !potentialStages.length && value.sourceStage !== 'UNKNOWN') continue;
    // Every allowed string is a fixed ASCII enum: escapes cannot be needed by this contract.
    const keys = [...textLine.matchAll(/"([^"\\]*)"\s*:/g)].map(match => match[1]);
    let valid = textLine.length <= 131072 && !textLine.includes('\\')
      && exactKeys(value, topKeys)
      && states.has(value.state) && categories.has(value.exceptionCategory)
      && Array.isArray(value.reportedExceptionChain) && value.reportedExceptionChain.length <= 16
      && value.reportedExceptionChain.every(category => typeof category === 'string' && categories.has(category))
      && origins.has(value.reportedOrigin)
      && Array.isArray(value.reportedExceptionClassChain)
      && value.reportedExceptionClassChain.length === value.reportedExceptionChain.length
      && value.reportedExceptionClassChain.every((name, index) => typeof name === 'string'
        && classNames.has(name)
        && value.reportedExceptionChain[index] === (name === 'UNKNOWN' ? 'UNKNOWN' : contract.classes[name]));
    const frame = value.reportedOwnFrame;
    if (valid && frame !== null) {
      const spec = frame !== null && typeof frame === 'object'
        && Object.prototype.hasOwnProperty.call(contract.frames, frame.symbol)
        ? contract.frames[frame.symbol] : null;
      valid = exactKeys(frame, ['line', 'symbol']) && spec !== null
        && spec.stages.includes(value.sourceStage) && spec.origin === value.reportedOrigin
        && Number.isSafeInteger(frame.line) && frame.line >= 1 && frame.line <= spec.maxLine;
    }
    const controllerState = value.state === 'UNIQUE' || value.state === 'REPORTED_PARTIAL_LOG_FORMAT';
    const fallbackState = value.state === 'REPORTED_NO_CONTROLLER'
      || value.state === 'REPORTED_PARTIAL_LOG_FORMAT_NO_CONTROLLER';
    const gatewayState = value.state === 'REPORTED_GATEWAY'
      || value.state === 'REPORTED_GATEWAY_PARTIAL_LOG_FORMAT';
    if (valid && controllerState) {
      valid = value.reportedOrigin === contract.stageOrigins[value.sourceStage];
    } else if (valid && (fallbackState || gatewayState)) {
      valid = value.reportedOrigin === (gatewayState
        ? 'GATEWAY_WEBFLUX' : contract.stageOrigins[value.sourceStage])
        && value.reportedExceptionChain.length >= 1
        && value.exceptionCategory === value.reportedExceptionChain[value.reportedExceptionChain.length - 1];
    } else if (valid) {
      valid = value.reportedOrigin === 'UNKNOWN'
        && value.exceptionCategory === 'UNKNOWN' && value.reportedExceptionChain.length === 0
        && value.reportedExceptionClassChain.length === 0 && frame === null;
    }
    const expectedKeys = frame === null ? topKeys : [...topKeys, 'line', 'symbol'];
    valid = valid && keys.length === expectedKeys.length
      && expectedKeys.every(key => keys.filter(observed => observed === key).length === 1);
    if (!valid || (target && (potentialStages.length !== 1 || potentialStages[0] !== value.sourceStage))) {
      if (target || potentialStages.length) {
        invalidClosedCandidateCount++;
        for (const stage of new Set([...potentialStages, ...(target ? [value.sourceStage] : [])])) rejected[stage]++;
      }
      continue;
    }
    if (value.sourceStage === 'UNKNOWN') { unknownStageCount++; continue; }
    if (target) by[value.sourceStage].push(value);
  }
  return {
    records: stages.map(sourceStage => ({
      sourceStage,
      count: by[sourceStage].length,
      outcome: by[sourceStage].length === 1 && rejected[sourceStage] === 0 ? by[sourceStage][0] : null,
    })),
    invalidClosedCandidateCount,
    unknownStageCount,
  };
}

