const crypto=require('node:crypto');
const contract=__CONTRACT_JSON__;
const source=__SOURCE_JSON__;
const project=eval('('+source+')');
let count=0;const labels=[];
const json=JSON.stringify,a=contract.stages[0],s=contract.stages[1];
function test(name,f){f();count++;labels.push(name);}
const serializeClass=Object.keys(contract.classes).find(x=>contract.classes[x]==='HTTP_SERIALIZATION');
assert.ok(serializeClass);assert.equal(contract.classes['org.springframework.web.server.ResponseStatusException'],'HTTP_STATUS');
const rec=(p={})=>({state:'REPORTED_NO_CONTROLLER',sourceStage:a,exceptionCategory:'HTTP_SERIALIZATION',reportedExceptionChain:['HTTP_SERIALIZATION'],reportedOwnFrame:null,reportedOrigin:contract.stageOrigins[a],reportedExceptionClassChain:[serializeClass],...p});
const gw=(p={})=>rec({state:'REPORTED_GATEWAY',exceptionCategory:'HTTP_STATUS',reportedExceptionChain:['HTTP_STATUS'],reportedExceptionClassChain:['org.springframework.web.server.ResponseStatusException'],reportedOrigin:'GATEWAY_WEBFLUX',...p});
const read=v=>project(json(v));
const out=v=>read(v).records.find(x=>x.sourceStage===v.sourceStage).outcome;
function reject(name,v){test(name,()=>{const r=read(v);assert.equal(r.records.find(x=>x.sourceStage===v.sourceStage).outcome,null);assert.equal(r.invalidClosedCandidateCount,1);assert.ok(!json(r).includes('PRIVATE_SECRET_SENTINEL'));});}
function rawReject(name,raw){test(name,()=>{const r=project(raw);assert.equal(r.records[0].outcome,null);assert.ok(r.invalidClosedCandidateCount>=1);assert.ok(!json(r).includes('PRIVATE_SECRET_SENTINEL'));});}
for(const stage of contract.stages){
 for(const state of ['UNIQUE','REPORTED_PARTIAL_LOG_FORMAT','REPORTED_NO_CONTROLLER','REPORTED_PARTIAL_LOG_FORMAT_NO_CONTROLLER']){
  const r=rec({sourceStage:stage,reportedOrigin:contract.stageOrigins[stage],state});test(stage+'_'+state,()=>assert.deepEqual(out(r),r));
 }
 for(const state of ['REPORTED_GATEWAY','REPORTED_GATEWAY_PARTIAL_LOG_FORMAT']){
  const r=gw({sourceStage:stage,state});test(stage+'_'+state,()=>assert.deepEqual(out(r),r));
 }
}
for(const [name,category] of Object.entries(contract.classes)){
 const r=gw({exceptionCategory:category,reportedExceptionChain:[category],reportedExceptionClassChain:[name]});test('finiteClass_'+name,()=>assert.deepEqual(out(r),r));
}
test('knownOuterUnknownLeaf',()=>{const r=gw({exceptionCategory:'UNKNOWN',reportedExceptionChain:['HTTP_STATUS','UNKNOWN'],reportedExceptionClassChain:['org.springframework.web.server.ResponseStatusException','UNKNOWN']});assert.deepEqual(out(r),r);});
for(const state of ['UNIQUE','REPORTED_PARTIAL_LOG_FORMAT']){
 test(state+'_legacyEmptyChain',()=>{const r=rec({state,reportedExceptionChain:[],reportedExceptionClassChain:[]});assert.deepEqual(out(r),r);});
